create index if not exists idx_provider_outcomes_survey_id on catalogue.provider_outcomes(survey_id); create index if not exists idx_provider_outcomes_study_level_id on catalogue.provider_outcomes(study_level_id) where study_level_id is not null; create index if not exists idx_provider_outcomes_source_id on catalogue.provider_outcomes(source_id); create index if not exists idx_provider_outcomes_evidence_id on catalogue.provider_outcomes(evidence_id) where evidence_id is not null; create index if not exists idx_source_provider_mappings_verified_by on pipeline.source_provider_mappings(verified_by) where verified_by is not null; create index if not exists idx_external_study_area_mappings_verified_by on ref.external_study_area_mappings(verified_by) where verified_by is not null;
